public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the array has only one element, return a list containing a single list with that element
    if (nums.length == 1) {
        permutations.add(Arrays.asList(nums[0]));
        return permutations;
    }

    // Recursive case: for each element in the array, find its permutations and add them to the list of permutations
    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, 0, i);
        int[] remaining2 = Arrays.copyOfRange(nums, i + 1, nums.length);
        for (List<Integer> permutation : permute(remaining)) {
            permutation.add(current);
            permutations.add(permutation);
        }
        for (List<Integer> permutation : permute(remaining2)) {
            permutation.add(0, current);
            permutations.add(permutation);
        }
    }

    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    permute(nums, used, new ArrayList<>(), result);
    return result;
}

private void permute(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            permute(nums, used, current, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

