public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    String maxString = "";
    for (String s : strings) {
        if (s.length() > maxLength) {
            maxLength = s.length();
            maxString = s;
        }
    }
    int inverseLength = 0;
    String inverseString = "";
    for (String s : strings) {
        String currInverse = new StringBuilder(s).reverse().toString();
        if (currInverse.length() > inverseLength) {
            inverseLength = currInverse.length();
            inverseString = currInverse;
        }
    }
    int largestSubstring = Math.max(maxLength, inverseLength);
    return largestSubstring;
}

