public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@') {
                // check if the current cell is part of an existing oil deposit
                if (i > 0 && j > 0 && grid[i - 1][j - 1] == '@') continue;
                if (i > 0 && grid[i - 1][j] == '@') continue;
                if (i > 0 && j < grid[0].length - 1 && grid[i - 1][j + 1] == '@') continue;
                if (j > 0 && grid[i][j - 1] == '@') continue;
                if (j < grid[0].length - 1 && grid[i][j + 1] == '@') continue;
                if (i < grid.length - 1 && j > 0 && grid[i + 1][j - 1] == '@') continue;
                if (i < grid.length - 1 && grid[i + 1][j] == '@') continue;
                if (i < grid.length - 1 && j < grid[0].length - 1 && grid[i + 1][j + 1] == '@') continue;
                // if the current cell is not part of an existing oil deposit, increment the number of deposits
                numDeposits++;
            }
        }
    }
    return numDeposits;
}

