public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // create a graph with the given number of vertices and edges
    Graph graph = new Graph(n);
    for (int[] path : paths) {
        graph.addEdge(path[0], path[1]);
    }

    // mark the starting n-tersection as visited
    graph.getVertex(start[0]).setVisited(true);

    // perform BFS from the starting n-tersection to visit all n-tersections in the graph
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0]);
    while (!queue.isEmpty()) {
        int current = queue.remove();
        for (Edge edge : graph.getEdges(current)) {
            int neighbor = edge.getOther(current);
            if (!graph.getVertex(neighbor).isVisited()) {
                graph.getVertex(neighbor).setVisited(true);
                if (neighbor == end[0]) {
                    return "can be travelled";
                }
                queue.add(neighbor);
            }
        }
    }

    // if the ending n-tersection is not visited, return "cannot be travelled"
    if (!graph.getVertex(end[0]).isVisited()) {
        return "cannot be travelled";
    }

    // return "can be travelled" if the ending n-tersection is visited
    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph representation of the maze
    Graph graph = new Graph(n * n);
    for (int[] path : paths) {
        int fromNode = path[0] * n + path[1];
        int toNode = path[2] * n + path[3];
        graph.addEdge(fromNode, toNode);
    }

    // Breadth-first search to find a path from start to end
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0] * n + start[1]);
    boolean[] visited = new boolean[n * n];
    visited[start[0] * n + start[1]] = true;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (node == end[0] * n + end[1]) return "can be travelled";
        for (int neighbor : graph.getNeighbors(node)) {
            if (!visited[neighbor]) {
                queue.add(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a boolean matrix to represent the visited n-tersections
    boolean[][] visited = new boolean[n][n];
    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;
    // Create a queue to store the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();
    // Add the starting n-tersection to the queue
    queue.add(start);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();
        // If the current n-tersection matches the ending n-tersection, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        // Loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // If the current n-tersection has a path to the adjacent n-tersection and it has not been visited, mark it as visited and add it to the queue
            if (path[0] == current[0] && path[1] == current[1] && !visited[path[0]][path[1]]) {
                visited[path[0]][path[1]] = true;
                queue.add(path);
            }
        }
    }
    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    if (!visited[end[0]][end[1]]) {
        return "cannot be travelled";
    }
    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    return canTravelMazeHelper(start, end, paths, visited, 0);
}

private static String canTravelMazeHelper(int[] curr, int[] end, int[][] paths, boolean[] visited, int pathIdx) {
    if (curr[0] == end[0] && curr[1] == end[1]) {
        return "can be travelled";
    }
    visited[curr[0] * n + curr[1]] = true;
    for (int[] neighbor : paths[curr[0] * n + curr[1]]) {
        if (!visited[neighbor]) {
            String result = canTravelMazeHelper(neighbor, end, paths, visited, pathIdx);
            if (result.equals("can be travelled")) {
                return result;
            }
        }
    }
    return "cannot be travelled";
}

