    int weekday = (int)((26 * month - 2) / 10 + day + year + (year / 4) + (6 * (year / 100) + (year / 400)) - 2 * (year / 100) - (year / 400)) % 7;
    return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[weekday];
}

