}

public int search(int[] nums, int target) {
    int start = 0;
    int end = nums.length - 1;
    while (start <= end) {
        int mid = (start + end) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[start] <= nums[mid]) {
            if (nums[start] <= target && target < nums[mid]) {
                end = mid - 1;
            } else {
                start = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[end]) {
                start = mid + 1;
            } else {
                end = mid - 1;
            }
        }
    }
    return -1;
}

int search(int[] nums, int target) {
    // Find the pivot k
    int pivot = findPivot(nums);
    // Search in the rotated part
    int index = searchRotated(nums, 0, pivot - 1, target);
    if (index == -1) {
        return searchRotated(nums, pivot, nums.length - 1, target);
    }
    return index;
}

int findPivot(int[] nums) {
    int low = 0, high = nums.length - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (mid < nums.length - 1 && nums[mid] > nums[mid + 1]) {
            return mid + 1;
        }
        if (mid > 0 && nums[mid] < nums[mid - 1]) {
            return mid;
        }
        if (mid < nums.length - 1 && nums[mid] > nums[0]) {
            low = mid + 1;
        } else if (mid > 0 && nums[mid] < nums[0]) {
            high = mid - 1;
        } else {
            return 0;
        }
    }
}

int searchRotated(int[] nums, int low, int high, int target) {
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (target < nums[mid]) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return -1;
}

