public double trimMean(int[] arr) {
    int n = arr.length;
    int idxSmall = (int) Math.floor(n * 0.05);
    int idxLarge = (int) Math.floor((n - 1) * 0.05);
    Arrays.sort(arr);
    int sum = 0;
    for (int i = idxSmall; i < n - idxLarge; i++) {
        sum += arr[i];
    }
    return (double) sum / (n - idxSmall - idxLarge);
}

