    int n = arr.length;
    int trimLength = (int) Math.floor(n * 0.05);
    int[] trimmedArr = Arrays.copyOfRange(arr, trimLength, n - trimLength);
    double sum = 0;
    for (int num : trimmedArr) {
        sum += num;
