public double trimMean(int[] arr) {
    // Sort the array
    Arrays.sort(arr);

    // Calculate the size of the trimmed array
    int trimSize = (int) Math.ceil(arr.length * 0.90) * 2;

    // Remove the smallest and largest elements
    int[] trimmed = Arrays.copyOfRange(arr, trimSize / 2, arr.length - trimSize / 2);

    // Calculate the sum of the trimmed array
    int sum = 0;
    for (int i = 0; i < trimmed.length; i++) {
        sum += trimmed[i];
    }

    // Return the trimmed mean
    return (double) sum / (double) trimmed.length;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.ceil(n * 0.05); // remove 5% of smallest and largest elements
    Arrays.sort(arr);
    int[] trimmedArr = Arrays.copyOfRange(arr, k, n - k);
    double mean = trimmedArr.stream().mapToDouble(x -> (double) x).average().getAsDouble();
    return mean;
}

