public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] sums = new int[n];
    for (int i = 0; i < n; i++) {
        sums[i] = arr[i] % k;
        if (sums[i] == 0) {
            sums[i] = k;
        }
    }
    Arrays.sort(sums);
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        counts[sums[i]]++;
    }
    for (int i = 1; i < k; i++) {
        if (counts[i] > 0) {
            counts[k - i] += counts[i];
        }
    }
    return counts[0] == n / 2;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;

    // Queue for BFS and to keep track of visited nodes
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(0);

    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        for (int i = 0; i < edges[currentNode].length; i++) {
            int nextNode = edges[currentNode][i];
            if (hasApple[currentNode] && distances[currentNode] + 2 < distances[nextNode]) {
                distances[nextNode] = distances[currentNode] + 2;
            }
            if (distances[nextNode] > distances[currentNode] + 1) {
                distances[nextNode] = distances[currentNode] + 1;
            }
            if (!hasApple[nextNode]) {
                queue.offer(nextNode);
            }
        }
    }

    return distances[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] positions = new int[n];
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            positions[i] = 1;
        } else {
            positions[i] = 2;
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < edges.length; j++) {
            if (edges[j][0] == i) {
                result += Math.min(positions[edges[j][1]], positions[i]);
            }
        }
    }
    return result;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < edges.length; k++) {
                if (edges[k][0] == j && edges[k][1] == i) {
                    dist[i] = Math.min(dist[i], dist[j] + (hasApple[j] ? 2 : 1));
                }
            }
        }
    }
    return dist[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    HashMap<Integer, List<Integer>> graph = new HashMap<>();
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        if (!graph.containsKey(u)) {
            graph.put(u, new ArrayList<>());
        }
        if (!graph.containsKey(v)) {
            graph.put(v, new ArrayList<>());
        }
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    boolean[] visited = new boolean[n];
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(0);
    visited[0] = true;

    int time = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int node = queue.poll();
            if (hasApple[node]) {
                time += 2;
            }
            for (int neighbor : graph.get(node)) {
                if (!visited[neighbor]) {
                    queue.offer(neighbor);
                    visited[neighbor] = true;
                }
            }
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] visited = new int[n];
    int[] distance = new int[n];
    int start = 0;
    int time = 0;

    for (int i = 0; i < n; i++) {
        visited[i] = 0;
        distance[i] = Integer.MAX_VALUE;
    }

    dfs(start, visited, distance, hasApple, edges);

    return time;
}

void dfs(int node, int[] visited, int[] distance, boolean[] hasApple, int[][] edges) {
    visited[node] = 1;
    for (int i = 0; i < edges.length; i++) {
        int neighbor = edges[i][0];
        if (neighbor == node && visited[neighbor] == 0 && hasApple[neighbor]) {
            distance[neighbor] = 1;
        } else if (neighbor == node && visited[neighbor] == 0 && !hasApple[neighbor]) {
            distance[neighbor] = 0;
        } else if (visited[neighbor] == 1 && distance[neighbor] != 0 && hasApple[neighbor]) {
            distance[neighbor] = Math.min(distance[neighbor], distance[node] + 1);
            time = Math.max(time, distance[neighbor]);
        } else if (visited[neighbor] == 1 && distance[neighbor] != 0 && !hasApple[neighbor]) {
            distance[neighbor] = Math.min(distance[neighbor], distance[node]);
        }
    }
    visited[node] = 2;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    String result = "";
    char lastChar = '\0';
    for (int i = 0; i < chars.length; i++) {
        char currChar = chars[i];
        if (currChar < lastChar || lastChar == '\0') {
            result += currChar;
        }
        if (currChar == lastChar) {
            i++;
        }
        lastChar = currChar;
    }
    lastChar = '\0';
    for (int i = chars.length - 1; i >= 0; i--) {
        char currChar = chars[i];
        if (currChar > lastChar || lastChar == '\0') {
            result += currChar;
        }
        if (currChar == lastChar) {
            i--;
        }
        lastChar = currChar;
    }
    return result;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    String result = "";
    while (chars.length > 0) {
        // pick the smallest character
        char smallest = chars[0];
        result += smallest;
        // remove the smallest character from the array
        for (int i = 0; i < chars.length - 1; i++) {
            chars[i] = chars[i + 1];
        }
        chars = Arrays.copyOf(chars, chars.length - 1);
        // pick the smallest character that is greater than the last appended character
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] > smallest) {
                smallest = chars[i];
                result += smallest;
                break;
            }
        }
        // remove the smallest character from the array
        for (int i = 0; i < chars.length - 1; i++) {
            chars[i] = chars[i + 1];
        }
        chars = Arrays.copyOf(chars, chars.length - 1);
        // pick the largest character
        char largest = chars[chars.length - 1];
        result += largest;
        // remove the largest character from the array
        for (int i = 0; i < chars.length - 1; i++) {
            chars[i] = chars[i + 1];
        }
        chars = Arrays.copyOf(chars, chars.length - 1);
        // pick the largest character that is smaller than the last appended character
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] < largest) {
                largest = chars[i];
                result += largest;
                break;
            }
        }
        // remove the largest character from the array
        for (int i = 0; i < chars.length - 1; i++) {
            chars[i] = chars[i + 1];
        }
        chars = Arrays.copyOf(chars, chars.length - 1);
    }
    return result;
}

