public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    while (chars.length > 0) {
        char smallest = chars[0];
        result.append(smallest);
        chars = Arrays.copyOfRange(chars, 1, chars.length);
        if (chars.length > 0) {
            char smallestGreater = getSmallestGreater(chars, smallest);
            if (smallestGreater != '\0') {
                result.append(smallestGreater);
                chars = Arrays.copyOfRange(chars, 1, chars.length);
            }
        }
        if (chars.length > 0) {
            char largest = chars[chars.length - 1];
            result.append(largest);
            chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
            if (chars.length > 0) {
                char largestLess = getLargestLess(chars, largest);
                if (largestLess != '\0') {
                    result.append(largestLess);
                    chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
                }
            }
        }
    }
    return result.toString();
}

private char getSmallestGreater(char[] chars, char smallest) {
    char smallestGreater = '\0';
    for (int i = 1; i < chars.length; i++) {
        if (chars[i] > smallest && (smallestGreater == '\0' || chars[i] < smallestGreater)) {
            smallestGreater = chars[i];
        }
    }
    return smallestGreater;
}

private char getLargestLess(char[] chars, char largest) {
    char largestLess = '\0';
    for (int i = 0; i < chars.length - 1; i++) {
        if (chars[i] < largest && (largestLess == '\0' || chars[i] > largestLess)) {
            largestLess = chars[i];
        }
    }
    return largestLess;
}

public boolean splitArraySameAverage(int[] nums) {
    double total = 0;
    for (int num : nums) {
        total += num;
    }
    double avg = total / nums.length;
    double leftSum = 0;
    int leftCount = 0;
    double rightSum = 0;
    int rightCount = 0;
    for (int i = 0; i < nums.length; i++) {
        if (leftSum + nums[i] <= avg) {
            leftSum += nums[i];
            leftCount++;
        } else {
            rightSum += nums[i];
            rightCount++;
        }
    }
    return leftSum / leftCount == rightSum / rightCount;
}

