    return leftSum / leftCount == avg;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    for (int i = 1; i <= n / 2; i++) {
        if (sum * 2 / n == nums[0] * i) {
            int[] arr1 = Arrays.copyOfRange(nums, 0, i);
            int[] arr2 = Arrays.copyOfRange(nums, i, n);
            return Arrays.stream(arr1).sum() == Arrays.stream(arr2).sum();
        }
    }
