    int sum1 = 0;
    int sum2 = 0;
    for (int i = 0; i < nums.length; i++) {
        if (i % 2 == 0) {
            sum1 += nums[i];
        } else {
            sum2 += nums[i];
        }
    }
    return sum1 == sum2 && sum1 == avg * nums.length / 2;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    if (n % 2 == 1) {
        return false;
    }
    int avg = sum / n;
    int leftSum = 0;
    for (int i = 0; i < n / 2; i++) {
        leftSum += nums[i];
    }
    if (leftSum == avg) {
        return true;
    }
    for (int i = n / 2; i < n; i++) {
        leftSum -= nums[i - n / 2];
        leftSum += nums[i];
        if (leftSum == avg) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int dp = Math.min(dp0 + cost[i], dp1 + cost[i]);
        dp0 = dp1;
        dp1 = dp;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int i, j;
    int[] dp = new int[cost.length];

    dp[0] = cost[0];
    dp[1] = cost[1];

    for (i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[cost.length-1], dp[cost.length-2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    return Math.min(minCostClimbingStairs(Arrays.copyOfRange(cost, 0, n - 1)), minCostClimbingStairs(Arrays.copyOfRange(cost, 1, n)));
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int memo[] = new int[n];
    memo[0] = cost[0];
    memo[1] = cost[1];
    for (int i = 2; i < n; i++) {
        memo[i] = Math.min(memo[i - 1], memo[i - 2]) + cost[i];
    }
    return Math.min(memo[n - 1], memo[n - 2]);
}

