public boolean hasAllCodes(String s, int k) {
    // Check if k is a valid substring length
    if (k <= 0 || k > s.length()) {
        return false;
    }

    // Create a set to store all possible substrings of length k
    Set<String> substrings = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    // Check if all substrings of length k are present in the set
    for (int i = 0; i + k <= s.length(); i++) {
        if (!substrings.contains(s.substring(i, i + k))) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        if (!s.contains(substring)) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    Set<String> subs = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        subs.add(s.substring(i, i + k));
    }
    Set<String> codes = new HashSet<>();
    for (int i = 0; i < Math.pow(2, k); i++) {
        String code = Integer.toBinaryString(i);
        while (code.length() < k) {
            code = "0" + code;
        }
        codes.add(code);
    }
    return subs.containsAll(codes);
}

