        if (!s.contains(substr)) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Declare a dynamic programming array
    int[] dp = new int[s.length() - k + 1];

    // Initialize the first element of the array
    dp[0] = 1;

    // Iterate over the remaining elements of the array
    for (int i = 1; i < dp.length; i++) {
        // Calculate the contribution from the previous element
        dp[i] = dp[i - 1] * 2;

        // If the contribution exceeds the maximum possible value, reset it to 1
        if (dp[i] > s.length()) {
            dp[i] = 1;
        }
    }

    // Return true if all elements of the array are greater than or equal to k
    return dp[dp.length - 1] >= k;
}

