public int findMinFibonacciNumbers(int k) {
    int minFibonacciNumbers = 0;
    int fib1 = 1;
    int fib2 = 1;
    int fibSum = fib1 + fib2;
    while (fibSum < k) {
        fib1 = fib2;
        fib2 = fibSum;
        fibSum = fib1 + fib2;
        minFibonacciNumbers++;
    }
    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    int i = 2; // Starting at 2 because we are given F1 = 1 and F2 = 1
    int a = 1, b = 1; // F1 and F2
    while (b < k) // Loop until the sum of Fibonacci numbers is > k
    {
        int c = a + b; // Find the next Fibonacci number
        a = b;
        b = c;
        ++i; // Increment the number of Fibonacci numbers summed
    }
    return i; // Return the number of Fibonacci numbers summed
}

public int findMinFibonacciNumbers(int k) {
    int[] fibonacci = new int[k + 1];
    fibonacci[0] = 0;
    fibonacci[1] = 1;
    for (int i = 2; i <= k; i++) {
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fibonacci[count];
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int count = 0;
    int n = 1;
    while (n < k) {
        n = n + findMinFibonacciNumbers(n);
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int fib1 = 1, fib2 = 1, fibN = 2;
    int count = 0;
    while (k > fibN) {
        if (k - fibN < fib1) {
            count++;
            k -= fibN;
        } else {
            fib1 = fib2;
            fib2 = fibN;
            fibN = fib1 + fib2;
            count++;
        }
    }
    return count;
}

