public static int kthFactor(int n, int k) {

  // 1. Start with a variable to store all the factors of n
  ArrayList<Integer> factors = new ArrayList<Integer>();

  // 2. Iterate from 1 to the square root of n
  for (int i = 1; i * i <= n; i++) {

    // 2a. If i divides n evenly, add it to the list of factors
    if (n % i == 0) {
      factors.add(i);

      // 2b. Add the other divisor if it is not equal to the current one
      if (i * i != n) {
        factors.add(n / i);
      }
    }
  }

  // 3. Return the kth factor if it is present, otherwise return -1
  if (k - 1 < factors.size()) {
    return factors.get(k - 1);
  } else {
    return -1;
  }
}

public int kthFactor(int n, int k) {
    List<Integer> factors = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }
    if (factors.size() < k) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (i + 1 < s.length() && (c ^ (c + 32)) == s.charAt(i + 1)) {
            continue;
        }
        sb.append(c);
    }
