    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            dp[i][j] = dp[i][j - 1] || ((prefixes[j][s.charAt(i) - 'a'] == 1) && dp[j][j - 1]);
        }
    }

    int max = 0;
