public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int longestLine = 0;

    // Check rows
    for (int i = 0; i < m; i++) {
        int currentLine = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                currentLine++;
            } else {
                longestLine = Math.max(longestLine, currentLine);
                currentLine = 0;
            }
        }
        longestLine = Math.max(longestLine, currentLine);
    }

    // Check columns
    for (int j = 0; j < n; j++) {
        int currentLine = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                currentLine++;
            } else {
                longestLine = Math.max(longestLine, currentLine);
                currentLine = 0;
            }
        }
        longestLine = Math.max(longestLine, currentLine);
    }

    // Check diagonal from top-left to bottom-right
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLine = 1;
                for (int k = 1; i + k < m && j + k < n; k++) {
                    if (mat[i + k][j + k] == 1) {
                        currentLine++;
                    } else {
                        longestLine = Math.max(longestLine, currentLine);
                        currentLine = 0;
                        break;
                    }
                }
                longestLine = Math.max(longestLine, currentLine);
            }
        }
    }

    // Check diagonal from top-right to bottom-left
    for (int i = 0; i < m; i++) {
        for (int j = n - 1; j >= 0; j--) {
            if (mat[i][j] == 1) {
                int currentLine = 1;
                for (int k = 1; i + k < m && j - k >= 0; k++) {
                    if (mat[i + k][j - k] == 1) {
                        currentLine++;
                    } else {
                        longestLine = Math.max(longestLine, currentLine);
                        currentLine = 0;
                        break;
                    }
                }
                longestLine = Math.max(longestLine, currentLine);
            }
        }
    }

    return longestLine;
}

public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, 1 + longestLineHelper(mat, i, j));
            }
        }
    }

    return maxLength;
}

private static int longestLineHelper(int[][] mat, int i, int j) {
    int m = mat.length;
    int n = mat[0].length;
    int count = 1;

    if (i == 0 || j == 0 || i == m - 1 || j == n - 1) {
        return count;
    }

    count += Math.max(longestLineHelper(mat, i + 1, j), longestLineHelper(mat, i - 1, j));
    count += Math.max(longestLineHelper(mat, i, j + 1), longestLineHelper(mat, i, j - 1));

    return count;
}

