    int[][] dirs = new int[][]{{0, 1}, {1, 0}, {1, 1}, {1, -1}};
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int[] dir : dirs) {
                int len = 1;
                int x = i + dir[0];
                int y = j + dir[1];
                while (x < m && x >= 0 && y < n && y >= 0 && mat[x][y] == 1) {
                    len++;
                    x += dir[0];
                    y += dir[1];
                }
                maxLen = Math.max(maxLen, len);
            }
        }
    }
    return maxLen;
}

