    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, horizontalLineLength(mat, i, j));
                maxLength = Math.max(maxLength, verticalLineLength(mat, i, j));
                maxLength = Math.max(maxLength, diagonalLineLength(mat, i, j));
                maxLength = Math.max(maxLength, antiDiagonalLineLength(mat, i, j));
            }
        }
    }
    return maxLength;
}

