        return dp[i][A.length - 1];
    }
    int count = 0;
    for (int j = i; j < A.length; j++) {
        if (isPerfectSquare(A[i] + A[j])) {
            count += countSquarePermutations(A, j + 1, dp);
        }
    }
    dp[i][A.length - 1] = count;
    return count;
}

