        ans.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int x = i;
        while (x > 0) {
            int digit = x % 10;
            if (digit > 0) {
                ans.add(digit);
            }
            x /= 10;
        }
    }
    return ans;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

