public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sum = 0;
    while (sum < n) {
        int square = (int) Math.pow(count + 1, 2);
        if (sum + square > n) {
            break;
        }
        sum += square;
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int i = 1;
    while (n > 0) {
        int sqrt = (int) Math.sqrt(i);
        int numSquares = n / sqrt;
        if (numSquares * sqrt == n) {
            count += numSquares;
            n -= numSquares * sqrt;
        }
        i++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int sqrt = (int) Math.sqrt(n);
        n -= sqrt * sqrt;
        count++;
    }
    return count;
}

