public static int minPerfectSquareSum(int n) {
    int count = 0;
    int currentSquare = 1;
    while (currentSquare <= n) {
        count++;
        currentSquare += count * count;
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        StringBuilder word = new StringBuilder(words[i]);
        words[i] = word.reverse().toString();
    }
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        StringBuilder reversedWord = new StringBuilder();
        for (int j = words[i].length() - 1; j >= 0; j--) {
            reversedWord.append(words[i].charAt(j));
        }
        reversedSentence.append(reversedWord);
        if (i != words.length - 1) reversedSentence.append(" ");
    }

    return reversedSentence.toString();
}

public static String reverseWords(String s) {
    // Split the input string into an array of words
    String[] words = s.split(" ");

    // Declare a new string builder to build the reversed string
    StringBuilder reversed = new StringBuilder();

    // Reverse each word and append it to the reversed string
    for (String word : words) {
        reversed.append(new StringBuilder(word).reverse().toString() + " ");
    }

    // Return the reversed string
    return reversed.toString().trim();
}

